        "content": "\"\"\"\r\nValidation modules for Word document processing.\r\n\"\"\"\r\n\r\nfrom .base import BaseSchemaValidator\r\nfrom .docx import DOCXSchemaValidator\r\nfrom .pptx import PPTXSchemaValidator\r\nfrom .redlining import RedliningValidator\r\n\r\n__all__ = [\r\n    \"BaseSchemaValidator\",\r\n    \"DOCXSchemaValidator\",\r\n    \"PPTXSchemaValidator\",\r\n    \"RedliningValidator\",\r\n]\r\n"
